import React, { useEffect, useRef, useState } from 'react';
import { Badge, Spinner } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { employeeFormContainer } from './formFieldData';
import Table from '../../components/Table';
import { findArrObj, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import { createVisitPlacesRequest, getVisitPlacesRequest, resetCreateVisitPlaces, resetGetVisitPlaces, resetUpdateVisitPlaces, updateVisitPlacesRequest } from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks'
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';

let isEdit = false;

function Index() {

    usePageTitle({
        title: 'Master',
        breadCrumbItems: [
            {
                path: '/view/visit-places',
                label: 'Master',
            },
            {
                path: '/view/visit-places',
                label: 'Visit Place',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', 'Master');
    const accessIds = (pageAccessData?.[0]?.children.find(val => val.label == "Visit Places").access || '')
        .split(',')
        .map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const { getVisitPlacesSuccess, getVisitPlacesList, getVisitPlacesFailure,
        createVisitPlacesSuccess, createVisitPlacesData, createVisitPlacesFailure,
        updateVisitPlacesSuccess, updateVisitPlacesData, updateVisitPlacesFailure, errorMessage

    } = appSelector((state) => ({
        getVisitPlacesSuccess: state.visitPlacesReducer.getVisitPlacesSuccess,
        getVisitPlacesList: state.visitPlacesReducer.getVisitPlacesList,
        getVisitPlacesFailure: state.visitPlacesReducer.getVisitPlacesFailure,

        createVisitPlacesSuccess: state.visitPlacesReducer.createVisitPlacesSuccess,
        createVisitPlacesData: state.visitPlacesReducer.createVisitPlacesData,
        createVisitPlacesFailure: state.visitPlacesReducer.createVisitPlacesFailure,

        updateVisitPlacesSuccess: state.visitPlacesReducer.updateVisitPlacesSuccess,
        updateVisitPlacesData: state.visitPlacesReducer.updateVisitPlacesData,
        updateVisitPlacesFailure: state.visitPlacesReducer.updateVisitPlacesFailure,

        errorMessage: state.visitPlacesReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Visit Places Name',
            accessor: 'visitPlacesName',
            sort: true,
        },
        {
            Header: 'Status',
            accessor: 'isActive',
            Cell: ({ row }) => (
                <div>
                    {row?.original?.isActive ? (
                        <Badge bg={'success'}>Active</Badge>
                    ) : (
                        <Badge bg={'danger'}>In active</Badge>
                    )}
                </div>
            ),
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const activeChecker = row.original.isActive
                const iconColor = activeChecker ? "text-danger" : "text-warning";
                const deleteMessage = activeChecker ? "You want to In-Active...?" : "You want to retrive this Data...?";
                return (
                    <div>
                        {
                            (roleIdforRole == 1 || _.includes(accessIds, '2')) &&
                            <span className="text-success  me-2 cursor-pointer" onClick={() => onEditForm(row.original, row.index)}>
                                <i className={'fe-edit-1'}></i>
                            </span>
                        }
                        {

                            (roleIdforRole == 1 || _.includes(accessIds, '3')) &&
                            <span
                                className={`${iconColor} cursor-pointer`}
                                onClick={() =>
                                    showConfirmationDialog(
                                        deleteMessage,
                                        () => onDeleteForm(row.original, row.index, activeChecker),
                                        'Yes'
                                    )
                                }>
                                {
                                    row?.original?.isActive ? <i className={'fe-trash-2'}></i> : <i className={'fas fa-recycle'}></i>
                                }
                            </span>
                        }
                    </div>
                )
            },
        },
    ];

    const [state, setState] = useState({});
    const [parentList, setParentList] = useState([]);
    const [selectedItem, setSelectedItem] = useState({});
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);

    const errorHandle = useRef();

    useEffect(() => {
        setIsLoading(true)
        dispatch(getVisitPlacesRequest());
    }, []);

    useEffect(() => {
        if (getVisitPlacesSuccess) {
            setIsLoading(false)
            setParentList(getVisitPlacesList)
            dispatch(resetGetVisitPlaces())
        } else if (getVisitPlacesFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetVisitPlaces())
        }
    }, [getVisitPlacesSuccess, getVisitPlacesFailure]);

    useEffect(() => {
        if (createVisitPlacesSuccess) {
            const temp_state = [createVisitPlacesData[0], ...parentList];
            setParentList(temp_state)
            showMessage('success', 'Created Successfully');
            closeModel()
            dispatch(resetCreateVisitPlaces())
        } else if (createVisitPlacesFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreateVisitPlaces())
        }
    }, [createVisitPlacesSuccess, createVisitPlacesFailure]);

    useEffect(() => {
        if (updateVisitPlacesSuccess) {
            const temp_state = [...parentList];
            temp_state[selectedIndex] = updateVisitPlacesData[0];
            setParentList(temp_state)
            isEdit && showMessage('success', 'Updated Successfully');
            closeModel()
            dispatch(resetUpdateVisitPlaces())
        } else if (updateVisitPlacesFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateVisitPlaces())
        }
    }, [updateVisitPlacesSuccess, updateVisitPlacesFailure]);

    const closeModel = () => {
        isEdit = false;
        onFormClear()
        setModal(false)
    }

    const onFormClear = () => {
        setState({
            ...state,
            visitPlacesName: '',
        });
    };

    const createModel = () => {
        onFormClear()
        isEdit = false;
        setModal(true)
    };

    const onEditForm = (data, index) => {
        setState({
            ...state,
            visitPlacesName: data?.visitPlacesName || "",
        });
        isEdit = true;
        setSelectedItem(data)
        setSelectedIndex(index)
        setModal(true)
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    }

    const onFormSubmit = async () => {
        const submitRequest = {
            visitPlacesName: state?.visitPlacesName || ""
        }
        if (/^[0-9]+(\.[0-9]+)?$/.test(state?.visitPlacesName)) {
            showMessage('error', "Alphabet Must be added");
            return;
        }
        if (isEdit) {
            dispatch(updateVisitPlacesRequest(submitRequest, selectedItem.visitPlacesId))
        } else {
            dispatch(createVisitPlacesRequest(submitRequest))
        }
    };

    const onDeleteForm = (data, index, activeChecker) => {
        const submitRequest = {
            isActive: activeChecker == 0 ? 1 : 0
        }
        setSelectedIndex(index)
        dispatch(updateVisitPlacesRequest(submitRequest, data.visitPlacesId))
    };

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={columns}
                    Title={'Visit Places List'}
                    data={parentList || []}
                    pageSize={5}
                    toggle={(roleIdforRole == 1 || _.includes(accessIds, '1')) ? createModel : false}
                />}

            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={'Visit Places'}
                modelSize={'md'}
                isEdit={isEdit}
                handleSubmit={handleValidation}>
                <FormLayout
                    dynamicForm={employeeFormContainer}
                    handleSubmit={onFormSubmit}
                    setState={setState}
                    state={state}
                    ref={errorHandle}
                    noOfColumns={1}
                    errors={errors}
                    setErrors={setErrors}
                />
            </ModelViewBox>
        </React.Fragment>
    );
}

export default Index;
